From 569cd54e8790d85903e9dbe85636d1eb2d04c552 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 09:32:44 +0100
Subject: [PATCH] desktoppackage/applet: keep popup size the same on every
 panel edge

The pixel kept for the separator line went to the height on horizontal
panels and to the width on vertical ones, so moving the panel changed
the popup's minimum and saved size. Now it is added in both directions.

BUG: 512298
---
 desktoppackage/contents/applet/CompactApplet.qml | 8 ++++----
 1 file changed, 4 insertions(+), 4 deletions(-)

diff --git a/desktoppackage/contents/applet/CompactApplet.qml b/desktoppackage/contents/applet/CompactApplet.qml
index 1aba2a5cd9..681381ba0e 100644
--- a/desktoppackage/contents/applet/CompactApplet.qml
+++ b/desktoppackage/contents/applet/CompactApplet.qml
@@ -314,7 +314,7 @@ PlasmaCore.ToolTipArea {
                         PropertyChanges {
                             separator.height: 1
                             appletParent.extraHeight: 1
-                            appletParent.extraWidth: 0
+                            appletParent.extraWidth: 1
                         }
                     },
                     State {
@@ -329,7 +329,7 @@ PlasmaCore.ToolTipArea {
                         }
                         PropertyChanges {
                             separator.width: 1
-                            appletParent.extraHeight: 0
+                            appletParent.extraHeight: 1
                             appletParent.extraWidth: 1
                         }
                     },
@@ -345,7 +345,7 @@ PlasmaCore.ToolTipArea {
                         }
                         PropertyChanges {
                             separator.width: 1
-                            appletParent.extraHeight: 0
+                            appletParent.extraHeight: 1
                             appletParent.extraWidth: 1
                         }
                     },
@@ -362,7 +362,7 @@ PlasmaCore.ToolTipArea {
                         PropertyChanges {
                             separator.height: 1
                             appletParent.extraHeight: 1
-                            appletParent.extraWidth: 0
+                            appletParent.extraWidth: 1
                         }
                     }
                 ]
-- 
